1	package nexusbench
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"net/http"
9		"net/url"
10		"slices"
11	)
12	
13	// benchRepositories are the only repositories reset may delete, in the order it
14	// deletes them: the group first, as it names the two others.
15	var benchRepositories = []string{dockerGroupRepository, dockerProxyRepository, dockerHostedRepository}
16	
17	// repositoryPath is the path of one repository, whatever its kind.
18	func repositoryPath(name string) string { return restAPI + "/repositories/" + name }
19	
20	// deleteRepository deletes one of benchRepositories. A repository that is not
21	// there is existed == false without an error. Any other name is refused before
22	// a request is sent: the bench never deletes what it did not create.
23	func (c *client) deleteRepository(ctx context.Context, name string) (existed bool, err error) {
24		if !slices.Contains(benchRepositories, name) {
25			return false, errors.New("refused to delete a repository that is not one of the bench")
26		}
27		op := "delete the repository " + name
28		resp, err := c.do(ctx, request{op: op, method: http.MethodDelete, path: repositoryPath(name)})
29		if err != nil {
30			return false, err
31		}
32		switch {
33		case resp.status == http.StatusNotFound:
34			return false, nil
35		case resp.status < 200 || resp.status > 299:
36			return false, &APIError{Op: op, Status: resp.status}
37		}
38		return true, nil
39	}
40	
41	// invalidateCache empties the cache of a proxy or group repository, the
42	// negative entries included. It writes no data, so it is not limited to the
43	// bench repositories.
44	func (c *client) invalidateCache(ctx context.Context, name string) error {
45		_, err := c.expect(ctx, request{
46			op: "invalidate the cache of " + name, method: http.MethodPost, path: repositoryPath(name) + "/invalidate-cache",
47		})
48		return err
49	}
50	
51	// unblockProxy puts docker-proxy back in service after its upstream came back:
52	// it sends again the configuration Provision writes (never one read back from the
53	// instance), which lifts the automatic block, then invalidates the cache. A
54	// proxy that does not exist is an error: up creates it.
55	func (c *client) unblockProxy(ctx context.Context, p Params) error {
56		path := dockerReposPath + "/proxy/" + dockerProxyRepository
57		found, err := c.get(ctx, "read the proxy repository "+dockerProxyRepository, path, nil, nil)
58		if err != nil {
59			return err
60		}
61		if !found {
62			return &BenchError{
63				Kind:  ProvisionFailed,
64				Cause: "the proxy repository " + dockerProxyRepository + " does not exist",
65				Check: upCheck,
66			}
67		}
68		for _, spec := range repositorySpecs(p) {
69			if spec.name != dockerProxyRepository {
70				continue
71			}
72			if err := c.write(ctx, "update the proxy repository "+spec.name, http.MethodPut, path, spec.config); err != nil {
73				return err
74			}
75		}
76		return c.invalidateCache(ctx, dockerProxyRepository)
77	}
78	
79	// requireAdmin makes one read as admin, so that a stored password the instance
80	// refuses stops the caller before it changes anything.
81	func (c *client) requireAdmin(ctx context.Context) error {
82		op := "check the admin account"
83		_, err := c.get(ctx, op, usersPath, url.Values{"userId": {adminUserID}}, nil)
84		var api *APIError
85		if errors.As(err, &api) && (api.Status == http.StatusUnauthorized || api.Status == http.StatusForbidden) {
86			return &BenchError{
87				Kind:  ProvisionFailed,
88				Cause: "Nexus refused the stored admin password, so nothing was changed",
89				Check: "the password in the secrets file may not match the instance; run `mise run nexus-bench:down` then `mise run nexus-bench:up`",
90				Err:   err,
91			}
92		}
93		return err
94	}
95	
96	// UnblockProxy puts docker-proxy back in service after its upstream came back:
97	// the configuration Provision writes, sent again, then its cache invalidated.
98	// It uses the stored admin password and nothing else, and refuses an upstream
99	// the bench did not deploy before any request. Every failure is a *BenchError.
100	// A nil out discards the progress lines.
101	func UnblockProxy(ctx context.Context, store SecretStore, baseURL string, p Params, out io.Writer) error {
102		if out == nil {
103			out = io.Discard
104		}
105		if !p.UpstreamIsBench() {
106			return customUpstreamError(p)
107		}
108		c, _, err := adminFromStore(ctx, baseURL, store)
109		if err != nil {
110			return asBenchError(err, p, baseURL)
111		}
112		defer c.closeIdle()
113		_, _ = fmt.Fprintln(out, "restore: putting "+dockerProxyRepository+" back in service")
114		if err := c.unblockProxy(ctx, p); err != nil {
115			return asBenchError(err, p, baseURL)
116		}
117		_, _ = fmt.Fprintln(out, "restore: "+dockerProxyRepository+" is back in service, its cache invalidated")
118		return nil
119	}
120

