96	// UnblockProxy puts docker-proxy back in service after its upstream came back:
97	// the configuration Provision writes, sent again, then its cache invalidated.
98	// It uses the stored admin password and nothing else, and refuses an upstream
99	// the bench did not deploy before any request. Every failure is a *BenchError.
100	// A nil out discards the progress lines.
101	func UnblockProxy(ctx context.Context, store SecretStore, baseURL string, p Params, out io.Writer) error {
102		if out == nil {
103			out = io.Discard
104		}
105		if !p.UpstreamIsBench() {
106			return customUpstreamError(p)
107		}
108		c, _, err := adminFromStore(ctx, baseURL, store)
109		if err != nil {
110			return asBenchError(err, p, baseURL)
111		}
112		defer c.closeIdle()
113		_, _ = fmt.Fprintln(out, "restore: putting "+dockerProxyRepository+" back in service")
114		if err := c.unblockProxy(ctx, p); err != nil {
115			return asBenchError(err, p, baseURL)
116		}
117		_, _ = fmt.Fprintln(out, "restore: "+dockerProxyRepository+" is back in service, its cache invalidated")
118		return nil
119	}
